    { "xorani hunter net on prin", { "exact", "A xorani hunter takes a huge net and throws it towards you." }, { "exact", "You watch as the net unfurls itself and traps you within its bindings." } },
    { "xorani priestess webs-stun", { "exact", "A xorani priestess removes a tarot card from a deck hidden within her garments. Rubbing the card quickly, she activates its hidden energies and flings the card in your direction. The card explodes in a violent flash, stunning you momentarily. When you regain control you realise you are entangled in a mass of invisible rope." } },
    { "xorani temple guard prone-ablaze", { "exact", "The charcoal eye upon the chest plate of a xorani temple guard begins to glow bright orange. The guard turns toward you and lets out a resounding warcry. The flaming eye rushes toward you, knocking you back and setting you ablaze." } },
    { "xorani temple guard prone-stun", { "exact", "A xorani temple guard slashes across your torso with his voulge, causing searing pain to ripple through your body to the point of fainting. As you regain consciousness, you remember you are mid-combat, yet your body is unresponsive." } },
    { "prin on fire", { "exact", "Rearing back his head, Commander Xu unleashes a fiery blast, sweeping back and forth to engulf all in a blazing inferno." } },
    { "prin ocean prone", { "exact", "The current from the pulling of the waves suddenly catches your footing and knocks you off your feet." } },
  },
  { "svo (aliases, triggers) / svo / svo Bashing triggers / Drazik's svo bashing triggers / isle of ulangi",
    { "ulangi prone", { "exact", "A majestic moose looks you straight in the eyes as he charges at you, his antlers connecting painfully to your chest and knocking you to the ground." } },
  },
  { "svo (aliases, triggers) / svo / svo Bashing triggers / Drazik's svo bashing triggers / istar jungle",
    { "istar prone", { "exact", "A monstrous gamling spider impales you with one of his many hooked legs, shaking you viciously before flinging you to the ground." }, { "exact", "Propelled by his giant back legs, a giant gwaeron springs towards you with head lowered, butting into your chest and sending you sprawling." }, { "exact", "A bearded pig gores you through the leg with one of his mighty tusks, sending you to your knees with a cry of anguish." }, { "exact", "Head lowered, a bearded pig charges at you from a distance, slamming his head into your gut and sending you sprawling." }, { "exact", "An agile kamatlan leaps through the air towards you, knocking you to the ground before swiping viciously at your exposed chest." }, { "exact", "Balancing on several sets of hind legs, a morpho caterpillar raises itself into the air and brings its head crashing down onto you painfully." }, { "exact", "A monstrous gamling spider sticks you with the end of one sharply hooked leg, pinning you to the ground mercilessly." } },
    { "istar stun", { "exact", "A monstrous gamling spider sticks you with the end of one sharply hooked leg, pinning you to the ground mercilessly." } },
    { "istar voyria", { "exact", "An agile kamatlan sinks his massive fangs into your leg, holding you still while the snakes extending from his shoulders attack from either side, biting you rapidly and repeatedly." } },
    { "istar para", { "exact", "You recoil with a sudden jerk as a blue-crowned ifrit careens into you, his contact with your skin sending a deep numbness deep into your musculature." }, { "exact", "With a quick jerk of his tiny head, a blue-crowned ifrit jabs his thin, wickedly sharp beak deep into your flesh as a hot, tingling sensation begins to spread through your bloodstream." }, { "exact", "The air around an armoured boalisk shimmers momentarily as he springs through the air towards you, fangs fully extended, and sinks them deep into your flesh as a slow-burning venom begins to travel through your bloodstream." } },
    { "istar transfix", { "exact", "A flying viper's eyes glow and change colour as it weaves through the air in an intricate pattern, transfixing you unawares." }, { "exact", "Accompanied by its haunting song, a brightly feathered olbi dances exotically before you, captivating you with its brilliant display of colour." } },
  },
  { "svo (aliases, triggers) / svo / svo Bashing triggers / Drazik's svo bashing triggers / istarion",
    { "Istarion arm break", { "exact", "Brandishing his fists boldly, a studious Tsol'dasi man swings viciously at your arm, breaking the bone with a sickening 'CRACK'." }, { "exact", "Brandishing his fists boldly, a joyful Tsol'dasi villager swings viciously at your arm, breaking the bone with a sickening 'CRACK'." }, { "exact", "Brandishing his fists boldly, a Tsol'dasi villager swings viciously at your arm, breaking the bone with a sickening 'CRACK'." }, { "exact", "Manipulating and compressing the air around her, a priestess of Life sends it whistling towards you. The gust of wind makes contact with your arm, nearly tearing it completely from the joint." }, { "exact", "With an aggravated growl, Shantuir, Watch Ascendant swings his staff violently at your arm which shatters upon contact with a sickening crunch." }, { "exact", "Brandishing his fists boldly, a grey-haired Tsol'dasi swings viciously at your arm, breaking the bone with a sickening 'CRACK'." }, { "exact", "A whisper spider outrider moves close to you with speed, grabbing an arm while slamming into your body. The force of the impact causes you to somersault onto the ground, dislocating your arm in the process." } },
    { "Istarion burns you", { "exact", "Pointing the spherical tip of the staff towards you, a watch spider outrider smiles before tapping it gently. A torrent of fire erupts from its surface, setting you aflame with its incandescence." }, { "exact", "With a quick, arcane utterance beneath his breath, an intense flame billows from atop his staff towards you." }, { "exact", "Grasping his blade of fire in both hands, an haruspex of Life brings it up over his head to bear upon you, the force of the blade's fiery impact causing it to disperse into thousands of motes of light." }, { "exact", "Grasping the blade of fire by the hilt, an haruspex of Life slashes into you." }, { "exact", "Celepharn, High Priest of Life calls forth a seething black ray shot through with veins of coruscating green fire, sending it flying towards you." }, { "exact", "Glowing missiles with fiery, flaming tails hurtle through the firmament towards you, exploding on impact in a shower of heat and sparks." }, { "exact", "Slowly generating them between his hands, Santhrar, a young prince summons five fist-sized globes of blue fire and sends them hurtling towards you." }, { "exact", "A mighty flame-wreathed phoenix materialises before Sariontari, Queen of Istarion, giving a clear, ringing call." } },
    { "Istarion leg breaks", { "exact", "A watch spider outrider sends the sphere end of her staff into one of your kneecaps, causing your bones to crack and pop unpleasantly." }, { "exact", "Seizing your leg within a grasp of blade-like limbs, a watch spiderling draws forth a pool of blood as it rakes through tendons." } },
    { "istarion prone", { "exact", "Roaring defiance, a Tsol'dasi boy charges into you with a shoulder tackle." }, { "exact", "With a single, smooth motion, a priestess of Life extends both arms in your direction as a wave of sheer, invisible force impacts your solar plexus, sending you flying." }, { "exact", "Arafaile, priestess of Life draws back and extends both arms as if to push you, never making contact. A moment later, you are thrown off your feet by a blast of nearly invisible, heat-like energy emerging from her fists." }, { "exact", "Tossing his head back and chanting an incantation to the heavens, an acolyte of Life summons down a pillar of holy fire from above, striking you to your knees." }, { "exact", "Moving quickly, a Tsol'dasi merchant plants one foot solidly in the side of your kneecap, causing your legs to buckle underneath you." }, { "exact", "Its eight red eyes gleaming, a sword spiderling utters a high-pitched shriek and skitters towards you, knocking you to the ground before retreating." }, { "exact", "A watch spiderling dances forward and hurls itself bodily at your chest." }, { "exact", "An ear-splitting shriek is emitted by a sword spider as it rushes towards you with furious speed, pinning you with the end of one hooked leg while using three others to stab into you repeatedly." }, { "exact", "A watch spider hurtles towards you with its eight legs fully outstretched, wrapping them tightly around your body and forcing you to tumble to the ground." }, { "exact", "With ocelei vibrating agitatedly, Saldesari Elisanil, Warren Ascendant's whisper spider lurches forward and brings its front legs crashing onto your shoulders, sending you to the ground." }, { "exact", "Hissing out a single word, Rheddrian Zorinar, Revered Counsellor conjures a mighty geyser of water that blasts you clean off your feet and sends you sprawling." }, { "exact", "A watch spider drops its entire body close to the ground and begins to spin in a clockwise direction, suddenly extending a single spindly leg to knock you off your feet." }, { "exact", "An opaque beam of blinding white light descends from the heavens, blasting you clear off your feet." }, { "exact", "Moving quickly, a Tsol'dasi merchant plants one foot solidly in the side of your kneecap, causing your legs to buckle underneath you." }, { "exact", "Sindrastar Nerrinth, the High Counsellor drops to the floor and sweeps her legs around at you, sending you sprawling." }, { "exact", "A whisper spider outrider moves close to you with speed, grabbing an arm while slamming into your body. The force of the impact causes you to somersault onto the ground, dislocating your arm in the process." } },
    { "istarion chill", { "exact", "Staring at you with icy blue eyes, an astrologer chants a brief incantation as you feel a sickly chill overcome your entire body." } },
    { "istarion webbed", { "exact", "In a sing-song voice, a priestess of Life completes an elaborate Tsol'dasi chant as ancient, gnarled roots emerge from the earth around your feet, ensnaring you on the spot." }, { "exact", "With a negligent wave of her hand, Rheddrian Zorinar, Revered Counsellor invokes a glittering mithril net into existence and sends it flying towards you." }, { "exact", "A whisper spider rears up on its back legs, delivering a fine stream of sticky silk that swiftly binds your limbs into motionlessness." }, { "exact", "The spinnerets of Saldesari Elisanil, Warren Ascendant's whisper spider twitch curiously before sending a thick strand of webbing at you." }, { "exact", "Tsui'zhir, Whisper Ascendant releases a series of three staccato whistles and his mount fires a burst of silk in your direction. As the sticky substance entangles you, you scream out in pain as you feel the threads begin to eat away at your skin." } },
    { "istarion kurthia", { "exact", "Khurthia, Sword Ascendant offers a sharp cry, to which her spider mount thunders forward, slamming its forehead into your chest forcefully as it tramples over you." } },
    { "istarion unknown", { "exact", "Saldesari Elisanil, Warren Ascendant cries a quick command to her whisper spider. The beast darts forward quickly in response, fangs gleaming as they sink into your flesh." } },
    { "istarion king", { "exact", "Avathar'an, the King of Istarion gives a mighty shout, fiery eyes turning furiously towards you as he hurtles one after another fireball slamming into your chest." } },
    { "istarion para", { "exact", "A whisper spider descends upon you with its massive fur-covered body, stabbing you deeply in the chest with a pair of wicked fangs." }, { "exact", "Eyes flashing with wrath, Vargalast Megurun, Revered Counsellor snaps his fingers sharply and you immediately find yourself unable to move any of your joints." }, { "exact", "Slowly and surely, Celepharn, High Priest of Life conjures the presence of three misty rings around your form, holding you in perfect stillness and preventing even your ability to breathe." } },
    { "celepharn para fear", { "exact", "Celepharn, High Priest of Life's face momentarily bloats and rots." }, { "exact", "His putrid visage wreaks of rotting flesh, and the sound of maggots squirming out of the various orifices of his skull can be discerned." } },
    { "istarion stun", { "exact", "Slowly and surely, Celepharn, High Priest of Life conjures the presence of three misty rings around your form, holding you in perfect stillness and preventing even your ability to breathe." }, { "exact", "Grasping his blade of fire in both hands, an haruspex of Life brings it up over his head to bear upon you, the force of the blade's fiery impact causing it to disperse into thousands of motes of light." }, { "exact", "Glowing missiles with fiery, flaming tails hurtle through the firmament towards you, exploding on impact in a shower of heat and sparks." }, { "exact", "Hissing out a single word, Rheddrian Zorinar, Revered Counsellor conjures a mighty geyser of water that blasts you clean off your feet and sends you sprawling." }, { "exact", "A shroud of crimson electricity descends upon you, shocking your body relentlessly." }, { "exact", "A mighty flame-wreathed phoenix materialises before Sariontari, Queen of Istarion, giving a clear, ringing call." }, { "exact", "You are suddenly arrested by the breathtaking vision of two unicorns moving soundlessly through the still, quiet jungle before you." }, { "exact", "A pinprick of light materialises between Arafaile, priestess of Life's hands, rapidly growing into a blindingly bright ball that disappears with a sudden flash, rendering you unable to see." }, { "exact", "Grasping his blade of fire in both hands, an haruspex of Life brings it up over his head to bear upon you, the force of the blade's fiery impact causing it to disperse into thousands of motes of light." }, { "exact", "An ear-splitting shriek is emitted by a sword spider as it rushes towards you with furious speed, pinning you with the end of one hooked leg while using three others to stab into you repeatedly." } },
    { "istarion blindaff", { "exact", "A pinprick of light materialises between Arafaile, priestess of Life's hands, rapidly growing into a blindingly bright ball that disappears with a sudden flash, rendering you unable to see." } },
    { "istarion transfix", { "exact", "Music lilts with a magical quality in the air around an acolyte of Life as he smiles, invitingly, at you, mesmerising you with his wild, ancient beauty." } },
    { "istarion nausea", { "exact", "Eriador, the Tsol'dasi merchant master pulls out a small silver dagger, previously concealed beneath his flowing garb, and plunges it into your stomach. As the blade is removed, blood begins to leak from the wound and you start to feel sick." } },
  },
  { "svo (aliases, triggers) / svo / svo Bashing triggers / Drazik's svo bashing triggers / ivory tower",
    { "ivory tower arm break", { "exact", "Raising one eyebrow at you with effortless disdain, Methats, the Divine Wind swings the barbed end of his silver mace to bear upon your shoulder, as the sound of bone splintering fills the air." }, { "exact", "Throwing her weight to the side, the Flowing Robes Champion brings her twin blades crashing down upon your arm in a single devastating blow." } },
