    { "Meropis loki", { "exact", "A horned viper's head darts forward suddenly, sinking huge, sharp fangs deep into your side." }, { "exact", "An energetic red turtle scrapes his nails across your skin, leaving venom dripping from the lacerations." }, { "exact", "You suddenly feel venom running through your veins." }, { "exact", "Leaping nimbly towards you, a thornback frog scrapes a large chunk of skin from your torso, leaving venom dripping from the wounds." }, { "exact", "Staring intensely, a bunyip slams himself into you, leaving numerous scratches on your skin dripping with some sort of venom." }, { "exact", "A putrid green crab bites at your feet, leaving a number of visible marks.Suddenly, you feel a strong venom running through your veins." } },
    { "Meropis Pacify", { "exact", "You suddenly feel unable to harm anyone or anything." } },
    { "Meropis Voyria", { "exact", "You suddenly feel a very powerful venom run through your veins." }, { "exact", "Suddenly, you begin to feel a burning sensation run through your veins." } },
    { "Meropis Blind", { "exact", "A sinister glubber scrapes his nails across your eyes, leaving you unable to see." } },
    { "Meropis Stupidity", { "exact", "You suddenly feel your mental capacity lower." }, { "exact", "Why must everything be so hard to understand?" }, { "exact", "Suddenly, you begin to feel your grip on reality fading." } },
    { "Meropis Fear", { "exact", "A sense of panic suddenly overcomes you, leaving you unaware of what to do next." }, { "exact", "Samial, a sleek Rajamala throws back his head and releases a fierce, rumbling roar that fills you with an ancient, primal urge to flee in terror." } },
    { "Meropis Ablaze", { "exact", "Staring intensely at you, a multicoloured boa constrictor causes your skin to spontaneously combust." }, { "exact", "In one swift motion, a bearded cook splashes a bottle of cooking oil over your body and ignites you with a lit match." }, { "exact", "Quickly yanking his tongs from the forge, Emmith, a sullen blacksmith showers you with burning hot cinders." } },
    { "Meropis BO and illness", { "exact", "Jadorno, a cloaked nobleman plunges a hand into a pouch at his belt, swiftly pulling it out and extending his arm to hurl a handful of noxious green powder into your face." } },
    { "Meropis fear and stupidity", { "exact", "You shriek with horror as Daerlain, an elderly noblewoman lays her shrivelled hands upon your temples and visions of chaos and madness swirl unchecked through your helpless mind." }, { "exact", "The fortress steward begins to rapidly read off the contents of his inventory list, his tongue moving impossibly quickly and leaving your head swirling in a daze of confusion." } },
    { "Meropis stun and prone", { "exact", "Duchess Alorina brings her fist hurtling forward to slam into your jaw with a decidedly unladylike degree of force." } },
    { "Meropis dizzy & prone", { "exact", "Swimming quickly around your body, a transparent cahno knocks you to the floor, leaving you rather dizzy and prone." } },
    { "Meropis Illness", { "exact", "An Ulsyndar guard draws back his arm and impales your leg on his wickedly sharp spear. As he withdraws his dripping blade, the sickening scrape of metal on bone causes your stomach to turn." }, { "exact", "An off-duty prison guard draws back his arm and impales your leg on his wickedly sharp spear. As he withdraws his dripping blade, the sickening scrape of metal on bone causes your stomach to turn." } },
  },
  { "svo (aliases, triggers) / svo / svo Bashing triggers / Qwindor's svo bashing triggers / Prin",
    { "Yuthka paralysis", { "exact", "Yuthka's eyes light up like burning coals as she lowers her head to your level, staring at you directly. You feel your muscles tighten right before you lose all feeling in your body." }, { "exact", "Turning quickly, Yuthka, the daemonic serpent shakes herself off and lets fly the acidic mucous that seeps from her body. The mucous attaches to your skin and causes it to bubble and boil." } },
    { "Yuthka limb break", { "exact", "Yuthka, the daemonic serpent races toward you with unbelievable speed. She encircles your body, coiling around you until your bones begin to shatter from the pressure. Suddenly she releases you, though your body cannot tell the difference." } },
  },
  { "svo (aliases, triggers) / svo / svo Bashing triggers / Qwindor's svo bashing triggers / Underworld",
    { "UW Scorpion", { "exact", "A deadly obsidian scorpion shoots both pincers forward in a double attack, plunging their razor-sharp points deep into you." } },
    { "UW Scorpion break", { "exact", "A deadly obsidian scorpion reaches out, grabs you in one of his huge pincers, and squeezes brutally." } },
    { "UW zombie break", { "exact", "A rotting zombie falls upon you heavily, snapping bones." } },
    { "UW DK prone", { "exact", "A steel-encased Death Knight pauses momentarily and emits a pulse of blinding, red light, taking away your balance." } },
    { "Ur Vamp aeon", { "exact", "The Ur'Vampire Gerzson bows his head, slumping forward as if in deep thought. You feel drawn, thinned, and the world around you speeds up noticeably." }, { "exact", "The Ur'Vampire Prioska bows her head, slumping forward as if in deep thought. You feel drawn, thinned, and the world around you speeds up noticeably." } },
    { "Ur' Vamp web", { "exact", "The Ur'Vampire Gerzson twirls quickly as a black mist rises from the ground in response. The mist moves quickly to envelope you with its ghastly choking fumes." } },
  },
  { "svo (aliases, triggers) / svo / svo Bashing triggers / Qwindor's svo bashing triggers",
    { "Ulgase aeon", { "exact", "With a wicked gleam in her eyes, Ulgase, the lich crone snaps her bony finger in front of you and the world suddenly seems to slow down." } },
    { "LHG Spider loki", { "exact", "A silver spider sinks its fangs into your body, you scream out in agony as a vicious venom tears through your body." } },
    { "LHG spider web", { "exact", "A silver spider spins around rearing up to spray you with a sticky webbing, which quickly entangles your limbs." } },
    { "Tsol'aa web", { "exact", "Deftly working her nimble fingers, Tsalinas, the weaver binds you in a complex weave of colourful thread." }, { "exact", "Kassan, the healer raises his arms with an angry glare, and thorny vines rise from the forest floor to entangle you." } },
    { "Tsol'aa arm break", { "exact", "Ta'lissu, the tattoo artist snarls and snatches your wrist, twisting it behind your back with a powerful jerk and snapping the bone." } },
    { "Jade serpent limb break", { "exact", "With a thunderous roar, a formidable jade sea serpent slithers around you and attempts to snap you in half with his powerful muscles." } },
    { "Tenwat legbreak", { "exact", "A pair of grasping hands grabs one of your calves and twists your leg as hard as possible. You feel an agonising pain and the bone snaps, tearing out of the flesh." } },
    { "belladona's keep arm break", { "exact", "Wrapping steel fingers around your arm, Grollum, the Sentinel crushes it effortlessly." }, { "exact", "A two-headed ogre brings his mace crashing down upon you, his other head whispering a chant that paralyzes you moments before it crunches into your arm." } },
    { "Bella paralyse", { "exact", "Your muscles stiffen and lock as Belladona, Queen of Vampires gazes at you hypnotically." } },
    { "Clockwork web", { "exact", "A wire-frame man whips a flexible length of wire around you, binding it tightly around you." } },
    { "Clockwork paralyse", { "exact", "You feel your muscles tightening as a wire-frame man scratches his claws into you." } },
    { "Atavian Legbreak", { "exact", "An atavian farmer fires a well-aimed kick at your leg, and you hear a sickening crunch." } },
    { "Lupine Hunting grounds paralyse and prone", { "exact", "With a deft manoeuvre a massive varkha whips his spear through the air slicing a deep gash in your chest then quickly thrusts the spear forward penetrating your gut with ease as the barbed head tears the wound open, as blood gushes from the wounds." } },
    { "LHG recklessnes", { "exact", "Opening its giant mouth a massive gohlbrorn clamps its sharp bony teeth into you ripping out a large chunk of flesh." } },
    { "Morindar legbreak", { "exact", "You fall to the floor, face distorted in agony as a statue of a haggard beggar crushes both your legs under his enormous foot." } },
    { "Morindar arm break", { "exact", "You hear the snapping of bone as a statue of a haggard beggar grabs you with both arms and crushes you in a tight embrace." } },
    { "Zaphar prone", { "exact", "A giant scorpion skitters forward and barrels into your kneecaps, sending you to the ground." } },
    { "Tapoa limb break", { "exact", "With an enraged howl, the king ape grabs your legs and lifts you above his head, whirling you about before effortlessly tossing you into the underbrush." }, { "exact", "Charging toward you with a shriek, the Vultubus tramples over your body, pounding you into the ground with his massive weight." } },
    { "Gulf arm break", { "exact", "Rocketing through the water, a redfin tuna rams into your arm, splintering the bone with agonising force." } },
    { "gulf leg break", { "exact", "Slipping a long tentacle around your lower body, a monstrous septacean slowly begins to squeeze, and you feel the bones of your legs crack under the intense pressure." } },
    { "Gulf prone", { "exact", "A school of hungry fish nibbles on the remains of Qwindor, who has succumbed to the teeth and tentacles of a monstrous septacean." } },
    { "Quisalis arm break", { "exact", "With an invigorated shout, a Quisalis sentry hacks into your arm with a vicious swing of his halberd." } },
    { "Azdun zombie paralyse and prone", { "exact", "A noxious fume squirts out of a decaying zombie, making your jaw tighten and knocking you to the ground." } },
    { "Squid arm break", { "exact", "A long tentacle reaches out to grab you, but you escape it at the last moment. As the tentacle passes by you it slams into your arm with a mighty force." } },
