  { "svo (aliases, triggers) / svo / svo Bashing triggers",
    { "A'dene", { "exact", "A'dene, Priestess of the Holy Three utters a prayer and smites your arm." }, { "exact", "It breaks with a loud 'CRACK'." } },
    { "Ablaze", { "exact", "Ulgase, the lich crone conjures a large flame within her bony palm. Shaping it into a fiery fireball, she sends it flying into the room, scorching your flesh and setting you on fire." }, { "exact", "Toogar, the ursu shaman reaches into his small satchel and produces a vial of bubbling liquid which he throws at you, the vial shattering and covering you with burning liquid." }, { "exact", "Eyes searching wildly, an ogre cook spies his recipe book on the floor. Scooping it up in one filthy hand, he sets it aflame and tosses it directly at your face." }, { "exact", "Reaching into a burlap sack, an orc cook retrieves a fistful of decomposing kitten corpses. Quickly lighting them on fire with the cooking spit, he grunts and throws them at you." }, { "exact", "Enuru, the Bane of Karbaz raises his hands into the air and invokes a blast of fire that lands upon your chest, sending you down to the floor." }, { "exact", "Tiamenjiara, the court conjuror rubs her hands briskly together, spreading them to reveal a growing ball of flame. With a forceful gesture she hurls the fire toward you, scorching your flesh." }, { "exact", "A colossal water strider suddenly turns his backside towards you and sprays an acidic liquid across your torso." }, { "exact", "Holding her golden candelabra in front of her, Ilucara Pelendur, Advisor to the Shah suddenly spits out a foul, noxious liquid into the flames with great force. As the fire comes into contact with the now-airborne fluid, a raging lash of flame begins to consume your skin, setting you aflame." }, { "exact", "A bloodied acolyte gives a maniacal cackle and summons a wave of fiery magic, blasting it at you and setting you on fire!" }, { "exact", "A sect ritualist gives a maniacal cackle and summons a wave of fiery magic, blasting it at you and setting you on fire!" }, { "exact", "Yurasta Tarcalion, the Thaumaturge reaches into his robes and grabs a random vial. He throws the vessel to the ground in front of you, and you watch in stunned surprise as it explodes with a green fire." }, { "exact", "Caurnn, the blacksmith howls as he brings his red-hot hammer crashing down on your head, singeing your skin." }, { "exact", "A Qurnok woman hurls the orb at you and it explodes upon contact." }, { "exact", "Twirling his staff above his head, Zen'fi Haar'chen sends a spinning pillar of fire across the chamber, burning everything in its path." }, { "exact", "Muttering a few arcane phrases under her breath, Sindrastar Nerrinth, the High Counsellor rapidly generates a ball of searing fire between the palms of her hands. Moments later, she sends it hurtling through the air towards you, bursting on impact and engulfing you in flames. " }, { "exact", "She opens her small mouth and lets loose a lash of fire to scorch your flesh." }, { "exact", "He opens his small mouth and lets loose a lash of fire to scorch your flesh." }, { "exact", "Waving his staff erratically, Zen'fi Haar'chen conjures a swirling fireball at you." }, { "exact", "Pulling the cap off her flask, Captain Kelley, Mayor of Mysia douses you in alcohol with one hand before flicking her cigar onto you with the other." }, { "exact", "Nhamdi, the elder closes his eyes and begins to chant rhythmically beneath his breath as drowsiness pricks at your mind, and you drift into sleep." }, { "exact", "A crimson pyrapede scuttles rapidly about your feet, setting your clothing on fire." }, { "exact", "Chanting a quick, forceful incantation, Balam Agab, the ogre archmage summons a ring of raging fire around you. The flames painfully sear your skin as you inhale the thick, black smoke." }, { "exact", "A pillar of living fire's fiery gaze lingers on you, and your skin and hair smoulder and then ignite." }, { "exact", "With a great sweep of his mighty staff, Maal'ryn Asgarai, Outrider Ascendant summons a great geyser of brightly burning liquid fire behind him that arcs upwards into the air and rains down furiously upon you." }, { "exact", "Anger blossoms in Faylinn, Lady of Unsidhe Court's eyes as she summons forth a barrage of fiery motes to torment you." }, { "exact", "While the tip is still hot, he quickly jabs you with the spear." }, { "exact", "A flame leaps upward from the surface of the molten lava as it flows over your foot, scalding you with its searing heat." }, { "exact", "Hethern Silwenil, Revered Counsellor's hands glow with a soft red light, before discharging two sheets of scorching flame that engulf you mercilessly." }, { "exact", "You suddenly feel your skin begin to burn and eventually ignite." }, { "exact", "Pointing his fingers in your direction, Begath, the Migri mage sends a massive fireball directly into your body." }, { "exact", "A House Feranki mage pulls out a small box the size of a human fist, shakes it, and throws it at you. On contact it explodes, burning you horribly." }, { "exact", "The light strikes you in the chest, suffusing your body in flames." } },
    { "Aeon", { "exact", "Oberion, King of the Fairies pinches a handful of iridescent powder from his satchel and blows it at you, causing your senses to whirl from a kaleidoscope of colour." }, { "exact", "Turga, the ursu midwife takes a syringe out of her satchel and stabs you with it, the contents rushing into your system and making you feel woozy and slow." }, { "exact", "A vicious swarm of acacidic ants climb upon each other, forming a thin tower before you. Suddenly, the ant at the top of the column begins to stare intensely into your eyes, leaving your world moving slower than usual." }, { "exact", "As the liquid enters your system, everything suddenly becomes so much slower." }, { "exact", "Screw-eye, the inmate superior sneers wickedly as he stabs into one of your veins with a foul needle. All movement slows as your body begins to swagger and sway sluggishly." }, { "exact", "A xorani priestess utters something under her breath. Slowly she raises her hand into the air, then makes a wide sweep across the room." }, { "exact", "Kamille, the Theran healer lifts her hands in a dramatic arc, bringing them together with a tremendous burst of bright light that slams into your chest." }, { "exact", "Chanting rhythmically under his breath, Derillin Yu'tar unleashes a blast of energy throughout the area." }, { "exact", "A weretigress mutters some arcane words sweeping her hands through the air, a bright flash emanates from her finger tips striking you solidly in the chest." }, { "exact", "A mad cackle from a cloaked assassin precedes the flicking of two Aeon tarots at you in quick succession, followed closely by a throwing dagger sinking into your chest." }, { "exact", "Ayod'nai, Whisperer of the All utters a string of words, and the world around you seems to slow down." } },
    { "Asthma", { "exact", "Chanting a quick, forceful incantation, Balam Agab, the ogre archmage summons a ring of raging fire around you. The flames painfully sear your skin as you inhale the thick, black smoke." }, { "exact", "In a lightning quick motion, a humble monk grabs your throat and begins to crush your windpipe, leaving you gasping for air." }, { "exact", "In a lightning quick motion, a young monk grabs your throat and begins to crush your windpipe, leaving you gasping for air." }, { "exact", "A mad cackle from a cloaked assassin precedes the flicking of two Aeon tarots at you in quick succession, followed closely by a throwing dagger sinking into your chest." } },
    { "Amnesia", { "exact", "A transparent cahno stares intensely into your eyes, leaving you unsure as to who or where you are." } },
    { "Bleeding (large)", { "exact", "The Ur'Vampire Zigana flicks her fingers in a rapid circular gesture. A swarm of screeching bats appears from nowhere, swerving and diving and sinking their tiny claws and fangs into any exposed areas, creating agonisingly painful wounds." }, { "exact", "The Ur'Vampire Tizane's eyes gleam as you are butchered with a wicked blow." } },
    { "Bleeding (little)", { "exact", "A fairy Knight of Sidhe whirls his weapon expertly, almost slicing you in half before impaling you upon its razor-sharp edge." }, { "exact", "A fairy Knight of Sidhe flies close to you and hacks into you with his halberd thrice, causing blood to gush from the wounds." }, { "exact", "A steel-encased Death Knight rises to his full height with a glare of unmitigated evil that pulls at your insides. The accompanying slash comes fast and low." }, { "exact", "Bringing his broadsword around in a slow arc, Commander Malrian Kyra carves a deep gash in your torso." }, { "exact", "A tundra wolf leaps onto you and knocks you over, repeatedly savaging your face with wicked claws." } },
    { "Bleeding (tiny)", { "exact", "A fairy Lady of Sidhe pulls a sharp crystal shard from her hair and punctures you with it." }, { "exact", "Issuing a cry to Moghedu, an elite mhun keeper jabs you violently with his rapier." }, { "exact", "Raising his spear above his head, a Qurnok guard quickly slashes open your torso." }, { "exact", "Using his spear as if it were an extension of his body, an ursu man thrusts the head of his weapon through your abdomen, causing a huge gash." }, { "exact", "An ursu man jumps at you and sinks his teeth into you." } },
    { "Both arms crippled", { "exact", "A young buckawn witchdoctor reaches forward with both hands and grabs your arms, shrivelling them within his grasp." } },
    { "Chill", { "exact", "A ghostly monk passes his ectoplasmic form through your body, causing you to shiver at the ghostly touch." }, { "exact", "A ghostly monk shimmers, then blows a chill breath at you, covering you with a graveyard frost." }, { "exact", "A tumbaga malagma points at you and utters a guttural, arcane word. Though your body's appearance does not change, you feel as cold and stiff as metal." }, { "exact", "The aching, bitter cold of the grave settles into your bones as Belladona, Queen of Vampires catches your arm in a vice-like grip. A wild power flashes in her eyes as she withdraws and you struggle with faltering consciousness." }, { "exact", "Summoning mystical energies, Ganorg, the Qurnok shaman blasts you with a gust of freezing cold air, shards of ice cutting into your flesh." }, { "exact", "As an oozing ferzel reaches out and envelops you in its frigid ooze, you feel the life being drained right out of you." }, { "exact", "Bringing her hands quickly together, two icicles appear in Kosuira, the child sorceress's clenched fists. With a swift motion she hurls the weapons at you, piercing your flesh with a shivering cold." }, { "exact", "Lowering her chin to her chest, Kosuira, the child sorceress murmurs a string of quiet words. Suddenly the wind picks up around you, icy cold and chilling you to the bone." }, { "exact", "With grim determination, Balai the Scorned blasts you with a thin stream of freezing water." }, { "exact", "A statue of an ice golem batters you with its elemental arms." }, { "exact", "The sound of grating ice fills the air as an ice wyrm opens its maw, spitting large ice chunks and freezing mist at you." }, { "exact", "An unnatural grating noise enters the air as a rush of freezing wind erupts outward from an ice golem, chilling you to the bone." }, { "exact", "A tundra mercenary whips a swirl of cold snow into your face before sweeping your legs." } },
    { "Crippled one unknown limb", { "exact", "Engorged and thoroughly fed, a rock leech wraps its massive girth about you, squeezing until your joints creak." }, { "exact", "Utterly heedless, the Leviathan catches you in the midst of its writhing and thrashing, crushing you with no visible effort." }, { "exact", "A goblin smith swings a hard throw to your limbs, and you feel numb." }, { "exact", "A single massive hand grasps you and flings you away as a colossal, hulking ghoul turns and stomps after you for the kill." }, { "exact", "A goblin slave swings a hard throw to your limbs, and you feel numb." }, { "exact", "Slicing his broadsword through the air, Knight Commander Lord Ethran Rani smashes it against one of your limbs, the force tearing through muscle and shattering bone." }, { "exact", "Slicing his broadsword through the air, Commander Malrian Kyra smashes it against one of your limbs, the force tearing through muscle and shattering bone." }, { "exact", "Slicing his broadsword through the air, Commander Farista Errikale smashes it against one of your limbs, the force tearing through muscle and shattering bone." } },
    { "Crippled two unknown limbs", { "exact", "With eyes closed, Malvoc, the unholy chants dark prayers as he gestures through the air, and with a sudden motion he flings his eyes open." }, { "exact", "You feel your bones snapping and crunching within your body." }, { "exact", "With three powerful strikes to your ribs, shoulder and sternum with his mace, an ogre captain knocks you to the floor, leaving you broken, bloody and bruised." }, { "exact", "Knocking your legs out from under you with his mace, an ogre captain moves in and stomps down on your body with all his weight." }, { "exact", "With a scream of sheer wrath, Mrughor, a spectral warlock lets loose a flying kick, striking you hard as the sound of breaking bone resounds." }, { "exact", "With surprising strength, Turga, the ursu midwife grabs you with powerful arms and squeezes, splintering bones." } },
    { "Confusion", { "exact", "Xulu, an orc witchdoctor whispers quietly to the air. The words begin to echo in your ears, growing louder until they reach a painful climax. As they subside, feelings of peace and confusion washes over your body." }, { "exact", "An orb of shimmering light emits a blinding flash of light and an explosive thunderclap that leaves you disoriented and confused." } },
    { "Clumsiness", { "exact", "The staff in Jerak, Captain of the Guard's hands becomes a blur as he slams it into your head three times in rapid succession, then finishes with a vicious thrust to your chest." }, { "exact", "A shriek of rage emits from Karinda Talkar, and the waters around you begin swirling. After a short moment, you are dragged into and whirlpool and whipped about in multiple circles, leaving you light-headed and dizzy." } },
    { "Disrupt", { "exact", "An orb of shimmering light emits a blinding flash of light and an explosive thunderclap that leaves you disoriented and confused." } },
    { "Dizziness", { "exact", "As Tybatha, the Oracle of Saiha'balan bows her head slightly toward you, your mind is battered by a strange telepathic force. The room blurs into a spinning mess." }, { "exact", "Calling upon her intimate link with the forests, Erato, spirit of the Eastern Ithmia summons a whirlwind of leaves to swirl about you, leaving your head spinning." }, { "exact", "Swinging his longsword at your head, a proud knight errant deals you a glancing blow across the temple." }, { "exact", "Swinging his longsword at your head, a sturdy knight deals you a glancing blow across the temple." }, { "exact", "A young monk balls up her small fist and pummels it into your stomach, causing you to feel nauseated while dizziness begins to overwhelm you." }, { "exact", "A young monk balls up his small fist and pummels it into your stomach, causing you to feel nauseated while dizziness begins to overwhelm you." }, { "exact", "Swinging suddenly with a spiteful backhand, Brendel, the fishmonger smacks you hard, sending your head ringing with dizziness." }, { "exact", "With a thunderous roar, a knight of the Siroccian Order slams his gauntleted fist hard into your face. " }, { "exact", "All of a sudden, the past becomes little more than a fuzzy haze." }, { "exact", "A shriek of rage emits from Karinda Talkar, and the waters around you begin swirling. After a short moment, you are dragged into and whirlpool and whipped about in multiple circles, leaving you light-headed and dizzy." }, { "exact", "A burly troll guard hums a gutteral chant under his breath and shoves you to the ground in a dizzy heap." } },
    { "Dementia", { "exact", "A lesser Penumbran fiend glances at you with a penetrating stare, its eyes burning with a madness that sets your mind aflame with insanity." } },
    { "Double arm break", { "exact", "Circling like a predator, Eschtar, the Swift steps in and slices you across both shoulders and you lose all feeling and control of your arms." } },
    { "Double leg break", { "exact", "Moving with astounding speed, a gargantuan ishkynd worm slings his body around your legs and squeezes them as hard as he can. You hear your bones snap as the pressure becomes higher and higher. " }, { "exact", "Flemming, the Ka'ah Botanist leaps at you and wrestles you to the ground, twisting your legs into an unnatural position as you hear the sound of snapping bones." }, { "exact", "Leaning even more heavily on her staff, Pirin, an elderly woman kicks you in the shins with all the strength she can muster." } },
    { "Epilepsy", { "exact", "A burly Theran guard wraps his massive hands around your head and squeezes." } },
    { "Fear", { "exact", "A bone golem opens its maw wide and lets forth an inhuman screech that fills you with utter dread as it rolls over you like a wave of death." }, { "exact", "The impenetrable, other-worldly form of the Leviathan inspires sheer, stark terror. Surely no mortal could stand against it." }, { "exact", "Smirnick, the Serpentlord quickly sinks his fangs into you, and fear spreads through you." }, { "exact", "A wild, frenzied look flickering across his face, a convulsing miner sinks his teeth into you." }, { "exact", "Bennett, a forlorn paladin looks directly into your eyes, and a deep fear fills your heart." }, { "exact", "As Cleric Lorlek intones a low prayer to the God, your blood begins to pound in your ears and an inexplicable fear encompasses you." }, { "exact", "Deftly a mhun conjuror summons a terrifying illusion, striking fear deep within your heart." }, { "exact", "A shiver of panic runs down your spine as the horror of a goblin zombie's existence strikes you." } },
    { "Illness", { "exact", "Entirely useless, a great grey slug oozes upon the ground furiously, and you feel sick to your stomach from the sight." }, { "exact", "A young monk balls up her small fist and pummels it into your stomach, causing you to feel nauseated while dizziness begins to overwhelm you." }, { "exact", "A young monk balls up his small fist and pummels it into your stomach, causing you to feel nauseated while dizziness begins to overwhelm you." }, { "exact", "The ghost of a drowned sailor exhales, and you gag from the horrible stench as its breath forms a noxious cloud around you." }, { "exact", "Eriador, the Tsol'dasi merchant master pulls out a small silver dagger, previously concealed beneath his flowing garb, and plunges it into your stomach. As the blade is removed, blood begins to leak from the wound and you start to feel sick." } },
    { "One arm crippled", { "exact", "A taryen man lifts himself up onto two limbs and uses his front limbs to squeeze your body, splintering bones." }, { "exact", "Jarak'lo, the Keeper lunges toward you, grabbing hold of your arm and easily snapping the bone. " }, { "exact", "You hear bones crack as Derik, the butcher brings the butt of his cleaver crashing down across your forearm." }, { "exact", "With practiced footwork, an orc sergeant quickly steps aside and slashes his axe deeply into your arm, shattering bones like glass." }, { "exact", "King Iasius locks your arms behind you in a crushing grip, and strains. He gives a cry of triumph at the 'crack' of your bones giving way." }, { "exact", "Desperately swinging at you with a hefty ledger, an audible crack accompanies sharp pain as Seril, a Shastaan merchant smacks your upper arm." }, { "exact", "With fluid grace, a large phocine flyer scythes through the air, striking your arm with a brutal blow from his tail." }, { "exact", "A reedy green buom wraps his branches around your arm, crushing it as he does so." }, { "exact", "A goblin zombie smashes his rotting fist into your arm and you hear bones crunch." }, { "exact", "You watch, in horror, as your arm shrivels up and becomes useless." }, { "exact", "In a lightning quick move, Ciglo, the historian grabs your wrist with one hand and presses up on your triceps with the other, applying pressure quickly which forces your arm to break." }, { "exact", "Grandmaster Kevadrin grabs your forearm and begins to twist, forcing your shoulder into a joint lock, sending a piercing pain throughout your body. Pressing harder, he causes your shoulder to separate." } },
    { "One leg crippled", { "exact", "Suddenly reversing his glaive, an elite guardsman skilfully smashes your kneecap with its weighted foot, sending you crashing to the floor in agony." }, { "exact", "With a savage growl, a young gryphon leaps onto your body, knocking you to the ground and crushing your legs." }, { "exact", "Rearing back, a queen leech lets out a piercing scream before slamming you against the wall with her corpulent body." }, { "exact", "A burly Theran guard smashes his mace into your leg with a satisfying 'CRACK'." }, { "exact", "Parmenides, the Arcadian philosopher lunges at you with a painful kick, and you hear the snapping of bone as his foot connects." }, { "exact", "A ghoul smith slams his hammer into your chest, stunning you. Quickly he recovers and smashes his hammer in an arc down on your leg, smashing it heavily." }, { "exact", "Frothing at the mouth and snarling with wild savagery, a feral dog clamps his powerful jaws onto your ankle, whipping his head back and forth until you hear a sickening snap." }, { "exact", " Flinging his body into yours, a crocodile connects painfully with your leg, breaking it in numerous places." }, { "exact", "A ghoul smith roars his fetid breath in your face, and raises his hammer in a two-handed blow. He slams it down on your chest, knocking you down onto your ass. As both of you attempt to regain your balance, the ghoul takes the opportunity to slam his boot into your knee, snapping it in half." }, { "exact", "You stumble as your leg shrivels into a useless appendage." }, { "exact", "A coruscating beam of blue energy leaps from the outstretched palm of Toogar, the ursu shaman, smashing into your body, picking you up, and knocking you to the ground." }, { "exact", "A vicious swarm of acacidic ants climb up your leg, crippling it with their bites as they do so." }, { "exact", "With a savage growl, a golden gryphon leaps onto your body, knocking you to the ground and crushing your legs." }, { "exact", "With a savage growl, a mother gryphon leaps onto your body, knocking you to the ground and crushing your legs." }, { "exact", "A brown-haired trainee rams the end of his wooden pole into your kneecap, the bone splintering as the stick is pushed forward." }, { "exact", "A diligent monk stands firm and attacks you with her staff, breaking your leg and causing you to fall to the ground." }, { "exact", "A dirty blond-haired trainee rams the end of his wooden pole into your kneecap, the bone splintering as the stick is pushed forward." }, { "exact", "A vicious dulosi majorus snaps quickly shut, breaking your leg in the process." }, { "exact", "A school of vicious piranha viciously attack your leg, ripping it to shreds." }, { "exact", "A humble monk stands firm and attacks you with his staff, breaking your leg and causing you to fall to the ground." }, { "exact", "With perfect balance, a humble monk executes a perfect roundhouse kick, delivering a powerful blow to your leg and causing it to shatter." } },
    { "Peace", { "exact", "You suddenly lose the ability to harm another." } },
    { "Paralysis", { "exact", "Your muscles stiffen and lock as the Ur'Vampire Zigana gazes at you hypnotically." }, { "exact", "Encircling your limbs with dangerous barbs, you feel pinpricks of pain from a massive jellyfish before your body goes numb." }, { "exact", "Your body fails to respond as her venom courses through your veins." }, { "exact", "A massive xabat stiffens his neck and head before spewing out a thin stream of yellowish-red poison upon you." }, { "exact", "Belladona, Queen of Vampires gazes at you hypnotically, and your muscles stiffen in response. A jewelled wrist flashes across your vision just before a slender fist makes contact with your throat." }, { "exact", "Bringing the handle of a nearby mop down at you in a forceful motion, she strikes your neck, jolting your entire body, and you find yourself unable to move." }, { "exact", "All of a sudden you feel your muscles seize up, leaving you unable to move." }, { "exact", "As the liquid enters your system, your limbs suddenly freeze, leaving you unable to move." }, { "exact", "A mummified troll guardian claps his hands together and breathes out a cloud of white dust that enters your lungs. Your body shudders." }, { "exact", "With a snarl, Torturer Abd punches you in the gut with a venomous barb attached to his stump of a wrist. A numbing sensation of paralysis spreads through your body rapidly as the cruel point pierces your skin and gouges internal organs." }, { "exact", "With a splintering crack a domesticated water buffalo bashes his head into your spine. A tingling sensation fills your body, followed by a complete loss of feeling." }, { "exact", "With a splintering crack a domesticated water buffalo bashes her head into your spine. A tingling sensation fills your body, followed by a complete loss of feeling." }, { "exact", "A chorus of whispers begins to emanate from all around you, paralysing you with fear." }, { "exact", "A cloaked assassin gazes pointedly at you, a blast of energy paralysing your body." }, { "exact", "Bennett, a forlorn paladin's hand passes through you, and he releases a pained sigh. Your body stiffens as a deep chill overtakes you." }, { "exact", "Your muscles stiffen and lock as a vicious ghast brushes you with a finger." } },
    { "Peace 2", { "exact", "Xulu, an orc witchdoctor whispers quietly to the air. The words begin to echo in your ears, growing louder until they reach a painful climax. As they subside, feelings of peace and confusion washes over your body." }, { "exact", "Bennett, a forlorn paladin gazes fondly at you, eyes shining with compassion and love; all anger fades from your heart." } },
    { "Prone", { "exact", "Growling aggressively, a feral grey lynx pounces onto you, knocking you to the ground." }, { "exact", "At lightning speed, a huge, ferocious crocodile whips its tail around and smacks you in the back, sending you rolling." }, { "exact", "Deftly pushing you to the ground, Grothgar, the ogre sergeant mercilessly stomps a massive foot upon you." }, { "exact", "Naggamantex, the torturer aims a swift kick at your torso, sending you backwards and onto the ground." }, { "exact", "A steel-encased Death Knight pauses momentarily and emits a pulse of blinding, red light, taking away your balance." }, { "exact", "Using his mass to his advantage, a giant toad rushes at you, taking you tumbling to the ground." }, { "exact", "Stamping its boulder-like foot, a hulking stone giant sends shockwaves through the ground, knocking you off your feet." }, { "exact", "Hefting a coil of rope from the ground, a burly dockhand whips one end out at you, catching your feet and tripping you up." }, { "exact", "Loosing an animal grunt, an orc soldier steps in close and trips you with the haft of his axe, smashing the flat of the blade against your skull as you fall." }, { "exact", "With a savage growl, a young gryphon leaps onto your body, knocking you to the ground and crushing your legs." }, { "exact", "Ducking behind his shield, a dwarf sentry charges you, knocking you to the ground." }, { "exact", "Commander Kalesh roars,enraged, and charges headlong at you, his considerable bulk giving himenough momentum to send you sprawling to the floor." }, { "exact", "Bellowing in rage, CommanderKalesh sweeps his axe in a wide arc, knocking down all who are in itsway." }, { "exact", "Lowering his head, a hobgoblin warrior charges toward you and knocks you back with his shoulder." }, { "exact", "Gliding in a swift spiral, a large phocine flyer slams into you, knocking you painfully to the ground." }, { "exact", "An incorporeal ghost tiger leaps into the air and pounces on you, sending you sprawling as his great claws dig into your body like daggers." }, { "exact", "With a roar of rage, a fell werewolf leaps at you, knocking you to the ground, raking his claws over your skin and ripping chunks of flesh from you with his sharp teeth." }, { "exact", "With three powerful strikes to your ribs, shoulder and sternum with his mace, an ogre captain knocks you to the floor, leaving you broken, bloody and bruised." }, { "exact", "Knocking your legs out from under you with his mace, an ogre captain moves in and stomps down on your body with all his weight." }, { "exact", "The ground begins to tremble and shake in answer to the rhythmic chanting of Mrughor, a spectral warlock, causing you to fall flat on your face." }, { "exact", "Enuru, the Bane of Karbaz raises his hands into the air and invokes a blast of fire that lands upon your chest, sending you down to the floor." }, { "exact", "Akarat, the Lorekeeper slaps you across the face, sending you tumbling to the ground." }, { "exact", "Ortha, the one-eyed vindicator smashes her staff across your head, knocking you backwards onto the ground. " }, { "exact", "With a feral snarl, a grey wolf leaps directly at you, burying his claws beneath your skin as he knocks you to the ground." }, { "exact", "Lunging towards you with six powerful legs extended, a powerful bara'hir knocks you to the ground and lacerates your flesh viciously with its numerous claws." }, { "exact", "Before the vast bulk of the Leviathan rushes a shockwave of air, that knocks you to the ground and stuns you, leaving your ears ringing." }, { "exact", "The earth shudders beneath the might of the Leviathan, knocking your feet out from under you and leaving you battered and bruised." }, { "exact", "Commander Kalesh roars, enraged, and charges headlong at you, his considerable bulk giving him enough momentum to send you sprawling to the floor." }, { "exact", "Gliding into the air and towards you, an Arcadian sentry kicks out, smashing his foot into your chin effortlessly and knocking you backwards." }, { "exact", "Scurrying across the ground swiftly and quietly, an armoured nahar quickly flattens itself, crawling beneath your legs and knocking you to the floor." }, { "exact", "Scurrying across the ground swiftly and quietly, an armoured nahar quickly flattens itself, crawling beneath your legs and knocking you to the floor." }, { "exact", "A noxious fume squirts out of a goblin zombie, making your jaw tighten and knocking you to the ground." }, { "exact", "A vicious, three-headed cerberus slams his massive body into you, sending you flying to the ground." }, { "exact", "Grithaxodon, the Beast smashes his huge meaty fists down against the ground, causing it to tremble enough to knock you over." }, { "exact", "The shadowy form of a whiptail stingray passes quickly overhead when suddenly, he veers and knocks you right off your feet." }, { "exact", "Dropping lightly to the floor, Alsimhinda, Queen of Zanzibaar swings a toned leg out from her many layers of silk, sweeping behind your feet to trip you." }, { "exact", "Lashing out at your arms, Kimitia, a Quisalis apprentice wraps her whip around your wrists and pulls you hard to the ground." }, { "exact", "A coruscating beam of blue energy leaps from the outstretched palm of Toogar, the ursu shaman, smashing into your body, picking you up, and knocking you to the ground." }, { "exact", "Using one of her massive paws to pin you to the ground, Leesha, the ursu packmother jabs your chest and stomach with her other paw, her sharp claws sinking deep into your flesh." }, { "exact", "Dropping lightly to the floor, Princess Qitala thrusts a leg from beneath her silken garments to trip you." }, { "exact", "-Commander Xu pulls back his massive arm and leaps forward onto you, knocking you to the ground and swiping his large claws into your flesh." }, { "exact", "A xorani hunter expertly dances around you while slipping his net around your neck. As you fall to the ground, he begins choking you." }, { "exact", "At a gesture from Erato, spirit of the Eastern Ithmia, a thick tree root protrudes from the ground and trips you off your feet." }, { "exact", "A single massive hand grasps you and flings you away as a colossal, hulking ghoul turns and stomps after you for the kill." }, { "exact", "The King Stag tramples over you with his enormous body." }, { "exact", "Telward slings a coil of rope from his shoulder and skilfully flings it at your legs, knocking you over and entangling your legs in the knots." }, { "exact", "Almost hurling her body to the ground, a young monk supports herself with her hands while spinning her leg around to strike you behind your knee, causing you to fall to the ground." }, { "exact", "A stern monk plants his staff perpendicular to the ground, using it as leverage to kick you in the chest with both feet, knocking you down." }, { "exact", "A diligent monk plants her staff perpendicular to the ground, using it as leverage to kick you in the chest with both feet, knocking you down." }, { "exact", "A humble monk plants his staff perpendicular to the ground, using it as leverage to kick you in the chest with both feet, knocking you down." } },
    { "Prone 2", { "exact", "Turning on his mount, Knight Commander Lord Ethran Rani lowers his lance and charges, the force of the impact knocking you to the ground." }, { "exact", "With relative ease, a wild caribou sends you tumbling to the floor as he punts his massive hooves into you." }, { "exact", "An azure koparfish slams his body violently into yours, causing you to fall to the floor." }, { "exact", "Forming a large row, a school of vicious piranha slam into your body, and send you flying to the floor." }, { "exact", "Stepping forward abruptly, a knight of the Siroccian Order slams his tower shield violently into you, knocking you to the ground and stunning you." }, { "exact", "A humble monk stands firm and attacks you with his staff, breaking your leg and causing you to fall to the ground." }, { "exact", "Forming a large row, a school of vicious piranha slam into your body, and send you flying to the floor." }, { "exact", "Springing forward, a wildcat soldier launches forward into you, sending you sprawling." }, { "exact", "Davkas grabs your arm and leg closest to him before picking you up and slamming your body ungracefully onto the ground." }, { "exact", "The dragon Yudhishthira unfurls his wings and beats them at the air. The gust sends you sprawling to the floor in a heap." }, { "exact", "A small horse knocks you down with his large head and tramples his hard hooves over your body." }, { "exact", "Crouching low, a bedraggled fisherman whirls his staff around, knocking your legs out from beneath you." }, { "exact", "Hissing out a single word, Balai the Scorned conjures a mighty geyser of water that blasts you clean off your feet and sends you sprawling." }, { "exact", "With a powerful shove, Sniglet, chief valet sends you sprawling to the ground." }, { "exact", "Swinging his cane in a low arc, Grationo Aurick catches your ankle with the crook and sends you sprawling to the ground." }, { "exact", "With a wild yell, Kallion, the adolescent rushes toward you, shoving you backwards." }, { "exact", "Wreathing his hand in kai energy, a Tanjinn monk strikes the ground with a closed fist and a loud, piercing shout. A shockwave of pale blue ripples outwards from the point of impact, nearly throwing you to the ground." }, { "exact", "A young worshipper's bare foot strikes the side of your knee, causing it to buckle and forcing you to the ground." }, { "exact", "Vaschel, the High Cleric flaps his large wings violently, blasting the room with a fierce gust of wind that knocks you off your feet." }, { "exact", "A wild centaur thrusts his spear deep into your belly, thrusting the tip and twisting with his strong arms. Quickly he pulls the spear out and you fall to the ground blood dripping from the massive trauma." }, { "exact", "With a roar of rage, a weretigress leaps at you, knocking you to the ground, raking her claws over your skin and ripping chunks of flesh from you with her sharp teeth." }, { "exact", "Commander Malrian Kyra brings the hilt of his broadsword down hard upon your head." }, { "exact", "With a joyful laugh, an energetic young boy runs around you and sweeps his leg underneath yours. Moments later, you find yourself lying on the ground." }, { "exact", "Clamping its powerful jaw of razor-sharp teeth onto your leg, an ageing mountain lion gives an almighty tug, sending you sprawling." }, { "exact", "A domesticated water buffalo charges at you, sending you sprawling to the ground." }, { "exact", "At a gesture from Clio, spirit of the Western Ithmia, a thick tree root protrudes from the ground and trips you off your feet." }, { "exact", "A Nuskuwen woman backs a few steps away and lifts her shoulder, charging to you in a few steps she rams the shoulder into you, leaving you sprawled across the ground." }, { "exact", "Without warning, Themus, a young cyclops shepherd charges toward you, crook held aloft as he rams the blunt end into your chest, sending you sprawling." }, { "exact", "A dirangi cub leaps up into the air with blinding speed, bouncing nimbly off a wall before landing directly on top of you, knocking you to the floor." }, { "exact", "A burly troll guard hums a gutteral chant under his breath and shoves you to the ground in a dizzy heap." }, { "exact", "Vingar, the Mercenary Captain smacks your forehead with the flat of his sword and shoves you onto the ground." }, { "exact", "Crouching low, Sonterro Rhodestrian, Mercenary Leader slaps his longsword across the back of your knees and knocks you to the ground." }, { "exact", "An off-duty guard drunkenly stumbles into you and knocks you off your feet." }, { "exact", "Qiland pivots his body to put all of his energy behind a powerful palmstrike to your sternum, forcing you to fall backwards onto the ground." }, { "exact", "Loosing an animal grunt, an orc soldier steps in close and trips you with the haft of his axe, smashing the flat of the blade against your skull as you fall." }, { "exact", "A Quisalis sentry dashes forward, slamming the haft of his halberd into the side of your knees, causing your legs to buckle." }, { "exact", "Lashing out at your arms, Kimitia, a Quisalis Assassin wraps her whip around your wrists and pulls you hard to the ground." }, { "exact", "The large frame of a large hound slams into you at full speed, knocking you off your feet." }, { "exact", "An elderly mage whirls in a circle, sending a massive blast of wind through the room that knocks you down." }, { "exact", "A female mage whirls in a circle, sending a massive blast of wind through the room that knocks you down." }, { "exact", "Lifting up her massive boot, Ilucara Pelendur, Advisor to the Shah thrusts her foot into your gut, knocking you to the ground." }, { "exact", "An ice wyrm coils its long tail around you, crushing your body within before tossing you aside." }, { "exact", "A tundra wolf leaps onto you and knocks you over, repeatedly savaging your face with wicked claws." }, { "exact", "An arctic wolf leaps onto you and knocks you over, repeatedly savaging your face with wicked claws." }, { "exact", "A tundra mercenary whips a swirl of cold snow into your face before sweeping your legs." }, { "exact", "Snarling in anger, a massive wendigo rushes toward you, bowling you over and smashing his club repeatedly into your exposed limbs." }, { "exact", "Tossing his club aside, a massive wendigo grabs you with a vice-like grip and easily lifts you up, then brutally slams you into the ground." }, { "exact", "The tentacles of a monstrous septacean flail wildly in all directions, slapping against you and sending you reeling backwards." }, { "exact", "You find yourself grasped ungently, thrust down through the whirlpool, and spat out again upon dry land." }, { "exact", "The staff in Jerak, Captain of the Guard's hands becomes a blur as he slams it into your head three times in rapid succession, then finishes with a vicious thrust to your chest." } },
    { "Prone 3", { "exact", "The ground beneath you begins to shake and it sends all around it tumbling to the ground." }, { "exact", "A flesh-eating slug rushes forward and bodily slams his bulk into you, knocking you to the ground." } },
    { "Quadbreak", { "exact", "His mouth moving rapidly, Avel, a hepatizon malagma gestures at you and you drop to the ground, all of your limbs suddenly heavy beyond belief." }, { "exact", "Black mists leap and writhe in response to a short, shrill chant from Belladona's lips. Inclining her head effortlessly, she sends the tendrils to sear your flesh, and your limbs shatter like glass under the fell caress." } },
