    { "Recklessness", { "exact", "A Dralhuan guard removes three needles from a small container previously concealed within his clothes and pushes them deep into your flesh. As the needles rest beneath your skin, you begin feeling at ease." } },
    { "Roped", { "exact", "Ryland slings a coil of rope from his shoulder and skilfully flings it at your legs, knocking you over and entangling your legs in the knots." }, { "exact", "Kurgo, the Ursu chief swings a net over his head and throws it over you, entangling you." }, { "exact", "Pulling a nearby lever, Nevon Talkar drops a thin sheet of netting across the chamber." }, { "exact", "Tiamenjiara, the court conjuror gestures sharply at your feet and vines seem to grow from the ground, winding around your body and entangling you." }, { "exact", "Telward slings a coil of rope from his shoulder and skilfully flings it at your legs, knocking you over and entangling your legs in the knots." }, { "exact", "Chanting with a harsh whisper, an ominous lich lashes you with a series of spectral ropes before sending them to entangle your limbs." }, { "exact", "A House Feranki mage throws a piece of rope at you. In mid-air, it expands into a mesh of netting that contracts around you." }, { "exact", "Damek, Feranki Magelord kneels and lays his huge hands flat on the ground, making circular motions in the dirt. A mass of thick, earthen tentacles rises from the ground to coil around you. You are ensnared!" }, { "exact", "Matteo, a marooned sailor spins around and throws his arms wide, casting a battered fishing net at you and entangling your limbs." } },
    { "Slickness", { "exact", "Flailing pathetically, a great grey slug attempts to cause you harm. Inadvertently, parts of your flesh become slick with slime." }, { "exact", "A squat scrag flails at you meekly, leaving a trail of putrid algae clinging to your flesh." } },
    { "Stun (0.5s)", { "exact", "Swinging his longsword at your head, a proud knight errant deals you a glancing blow across the temple." }, { "exact", "Swinging his longsword at your head, a sturdy knight deals you a glancing blow across the temple." }, { "exact", "An ursu man opens his mouth and lets out a mighty roar, making your ears ring and leaving you frazzled." }, { "exact", "Sinking into a horse stance, a diligent monk punches you directly in the gut, forcing the air from your lungs." }, { "exact", "Knight Commander Lord Ethran Rani brings the hilt of his broadsword down hard upon your head." }, { "exact", "An Ulsyndar guard pivots quickly and smashes the haft of his spear into the side of your head, making your ears ring." }, { "exact", "Stepping forward abruptly, a knight of the Siroccian Order slams his tower shield violently into you, knocking you to the ground and stunning you." }, { "exact", "Expertly throwing you off balance with a kick to the chest, a proud ducal guard brings the butt of his sword slamming down on your skull in a fierce blow." }, { "exact", "A bedraggled Ashtani foot soldier swings his shortsword above his head and brings the flat of the blade crashing down on your skull." }, { "exact", "Commander Malrian Kyra brings the hilt of his broadsword down hard upon your head." }, { "exact", "Commander Farista Errikale brings the hilt of his broadsword down hard upon your head." }, { "exact", "Gripping the handle with both hands, Duke Semiro brings his mace crashing down on your head." }, { "exact", "Sweeping his pickaxe in a wild arc, a blood-soaked dwarven miner catches your head a glancing blow with the thick, wooden shaft." }, { "exact", "Powering his tail, a redfin tuna speeds towards your head, his body connecting with a force that leaves your ears ringing." }, { "exact", "The Ur'Vampire Asztrik flicks his fingers in a rapid circular gesture. A swarm of screeching bats appears from nowhere, swerving and diving and sinking their tiny claws and fangs into any exposed areas, creating agonisingly painful wounds." }, { "exact", "Feinting a jab, a sword spider outrider brings the hilt of his other sword towards you, stunning you with its forceful impact into your skull." }, { "exact", "Raising herself up to her full height and glaring at you, an Arcadian noblewoman backhands you sharply in the mouth, stunning you." }, { "exact", "A lost spirit begins to chant in a long-forgotten language, and you stumble backwards as pain tears through your skull." }, { "exact", "Wreathing his hand in kai energy, a Tanjinn monk strikes the ground with a closed fist and a loud, piercing shout. A shockwave of pale blue ripples outwards from the point of impact, nearly throwing you to the ground." }, { "exact", "With a fearsome neigh, a wild kelpie rears up and stomps two hooves into your head and torso." }, { "exact", "A Brighthold watchman swings his arm around in a sweeping circle, slamming his lantern into your head. The lantern connects with a ferocious blow, stunning you momentarily and choking you with noxious fumes from the flame within." }, { "exact", "With a fearful gasp, Kavan, the first mate grasps his ledger firmly and swings it wildly at your head, connecting with a thud." }, { "exact", "Hard ice forms around the fist of a tundra mercenary as he punches you viciously in the temple." } },
